/**
 * KPIとして表示・グラフ切り替え可能な主要指標種別
 */
export type KpiMetricType = 'sales' | 'customers' | 'averageSpend';

/**
 * 選択可能な年度の型定義
 * 既存の既定年度に加えて動的な年度追加にも対応可能な拡張型
 */
export type YearOption = '2022' | '2023' | '2024' | (string & {});

/**
 * 月次実績および目標データモデル
 */
export interface MonthlyRecord {
  /** 対象月表記（例: '1月', '2月'） */
  month: string;
  /** 売上実績額（単位: 円） */
  sales: number;
  /** 来客数実績（単位: 人） */
  customers: number;
  /** 客単価実績（単位: 円、売上÷客数の四捨五入計算値） */
  averageSpend: number;
  /** 売上目標設定額（単位: 円） */
  targetSales: number;
  /** 来客数目標（単位: 人、将来拡張用オプショナル） */
  targetCustomers?: number;
  /** 目標客単価（単位: 円、将来拡張用オプショナル） */
  targetAverageSpend?: number;
}

/**
 * KPIサマリーカード表示用データモデル
 */
export interface KpiItem {
  /** KPIの指標識別子 */
  id: KpiMetricType;
  /** KPIの表示名称（例: '年間総売上'） */
  label: string;
  /** 当該年度の実績合計値または平均値 */
  value: number;
  /** 前年同期間の実績値 */
  previousValue: number;
  /** 数値の単位文字列（例: ' 円', ' 人'） */
  unit: string;
  /** 通貨記号などの接頭辞（例: '¥', ''） */
  prefix: string;
  /** 前年比増減率（単位: %、例: +5.2） */
  diffRate: number;
}

import { MonthlyRecord, YearOption } from '../types';

/**
 * 月次実績レコードを生成するヘルパー関数
 * 売上と客数から平均単価(averageSpend)を算出して整合性を担保する
 */
const createMonthlyRecord = (
  month: string,
  sales: number,
  customers: number,
  targetSales: number,
  targetCustomers?: number
): MonthlyRecord => {
  const averageSpend = customers > 0 ? Math.round(sales / customers) : 0;
  const targetAverageSpend =
    targetCustomers && targetCustomers > 0
      ? Math.round(targetSales / targetCustomers)
      : undefined;

  return {
    month,
    sales,
    customers,
    averageSpend,
    targetSales,
    ...(targetCustomers !== undefined && { targetCustomers }),
    ...(targetAverageSpend !== undefined && { targetAverageSpend })
  };
};

/** 2022年度月次実績データ（2023年比較用） */
export const salesData2022: MonthlyRecord[] = [
  createMonthlyRecord('1月', 3900000, 1350, 3800000, 1300),
