  createMonthlyRecord('6月', 3950000, 1320, 3900000, 1300),
  createMonthlyRecord('7月', 4800000, 1580, 4700000, 1550),
  createMonthlyRecord('8月', 5050000, 1630, 4900000, 1600),
  createMonthlyRecord('9月', 4050000, 1340, 4000000, 1320),
  createMonthlyRecord('10月', 4350000, 1420, 4200000, 1380),
  createMonthlyRecord('11月', 4450000, 1440, 4300000, 1400),
  createMonthlyRecord('12月', 5600000, 1780, 5400000, 1720)
];

/** 2023年度月次実績データ */
export const salesData2023: MonthlyRecord[] = [
