  createMonthlyRecord('2月', 3800000, 1250, 3800000, 1250),
  createMonthlyRecord('3月', 4600000, 1500, 4400000, 1450),
  createMonthlyRecord('4月', 4500000, 1460, 4300000, 1420),
  createMonthlyRecord('5月', 4900000, 1580, 4700000, 1530),
  createMonthlyRecord('6月', 4300000, 1390, 4200000, 1360),
  createMonthlyRecord('7月', 5200000, 1650, 5000000, 1600),
  createMonthlyRecord('8月', 5500000, 1720, 5300000, 1680),
  createMonthlyRecord('9月', 4400000, 1410, 4300000, 1380),
  createMonthlyRecord('10月', 4700000, 1480, 4500000, 1440),
  createMonthlyRecord('11月', 4800000, 1510, 4600000, 1470),
