/** 2024年度月次実績データ */
export const salesData2024: MonthlyRecord[] = [
  createMonthlyRecord('1月', 4580000, 1450, 4400000, 1420),
  createMonthlyRecord('2月', 4120000, 1310, 4000000, 1290),
  createMonthlyRecord('3月', 5080000, 1590, 4800000, 1520),
  createMonthlyRecord('4月', 4920000, 1520, 4700000, 1470),
  createMonthlyRecord('5月', 5350000, 1640, 5100000, 1580),
