  createMonthlyRecord('8月', 6020000, 1790, 5700000, 1720),
  createMonthlyRecord('9月', 4880000, 1470, 4700000, 1430),
  createMonthlyRecord('10月', 5190000, 1540, 4900000, 1480),
  createMonthlyRecord('11月', 5310000, 1560, 5000000, 1500),
  createMonthlyRecord('12月', 6750000, 1950, 6300000, 1850)
