/** 年度キーに対応する実績データマッピング */
const salesDataMap: Record<string, MonthlyRecord[]> = {
  '2022': salesData2022,
  '2023': salesData2023,
  '2024': salesData2024
};

/**
 * 指定年度の月次実績データを取得するデータアクセス関数
 * @param year 対象年度文字列
 * @returns 該当年度のMonthlyRecord配列
 */
export const getSalesDataByYear = (year: YearOption): MonthlyRecord[] => {
  return salesDataMap[year] || [];
};

import { KpiItem, KpiMetricType } from '../types';

interface KpiCardsProps {
  kpis?: KpiItem[];
  selectedMetric: KpiMetricType;
  onSelectMetric?: (metric: KpiMetricType) => void;
}

const numberFormatter = new Intl.NumberFormat('ja-JP');

const formatNumber = (val: number): string => {
  return numberFormatter.format(val);
};

const KpiCards = ({
  kpis = [],
  selectedMetric,
  onSelectMetric
}: KpiCardsProps) => {
  return (
    <div className="kpi-grid">
      {kpis.map((kpi) => {
        const isSelected = selectedMetric === kpi.id;
        const isPositive = kpi.diffRate > 0;
        const isNegative = kpi.diffRate < 0;

        let formattedDiff = `${kpi.diffRate.toFixed(1)}%`;
        let badgeIcon = '';
        let badgeClass = 'kpi-badge';

        if (isPositive) {
          formattedDiff = `+${kpi.diffRate.toFixed(1)}%`;
          badgeIcon = '▲ ';
          badgeClass = 'kpi-badge kpi-badge-positive';
        } else if (isNegative) {
          formattedDiff = `${kpi.diffRate.toFixed(1)}%`;
          badgeIcon = '▼ ';
          badgeClass = 'kpi-badge kpi-badge-negative';
        }

        const cardClass = isSelected ? 'kpi-card kpi-card-active' : 'kpi-card';

        return (
          <div
            key={kpi.id}
            className={cardClass}
            onClick={() => onSelectMetric?.(kpi.id)}
            role="button"
            tabIndex={0}
            aria-pressed={isSelected}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onSelectMetric?.(kpi.id);
              }
            }}
          >
            <div className="kpi-header">
              <span className="kpi-label">{kpi.label}</span>
              <span className={badgeClass}>
                {badgeIcon}{formattedDiff}
              </span>
            </div>

            <div className="kpi-value-row">
              <span className="kpi-value">
                {kpi.prefix}
                {formatNumber(kpi.value)}
                {kpi.unit}
              </span>
            </div>

            <div className="kpi-subtext">
              前年実績: {kpi.prefix}{formatNumber(kpi.previousValue)}{kpi.unit}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default KpiCards;

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  CartesianGrid
} from 'recharts';
import { MonthlyRecord, KpiMetricType } from '../types';

interface ChartSectionProps {
  data?: MonthlyRecord[];
  activeMetric: KpiMetricType;
  onChangeMetric?: (metric: KpiMetricType) => void;
}

const metricTabs: { id: KpiMetricType; label: string }[] = [
  { id: 'sales', label: '売上実績・目標' },
  { id: 'customers', label: '客数推移' },
  { id: 'averageSpend', label: '客単価推移' }
];

const metricConfig: Record<
  KpiMetricType,
  {
    yAxisFormatter: (val: number) => string;
    tooltipFormatter: (value: number | string | undefined, name: string | undefined) => [string, string];
  }
> = {
  sales: {
    yAxisFormatter: (val: number) => `${(val / 10000).toFixed(0)}万`,
    tooltipFormatter: (value, name) => [
      `¥${Number(value || 0).toLocaleString()}`,
      name ?? '売上'
    ]
  },
  customers: {
    yAxisFormatter: (val: number) => `${val}人`,
    tooltipFormatter: (value, name) => [
      `${Number(value || 0).toLocaleString()} 人`,
      name ?? '客数'
    ]
  },
  averageSpend: {
    yAxisFormatter: (val: number) => `¥${val.toLocaleString()}`,
    tooltipFormatter: (value, name) => [
      `¥${Number(value || 0).toLocaleString()}`,
      name ?? '客単価'
    ]
  }
};

const ChartSection = ({
  data = [],
  activeMetric,
  onChangeMetric
}: ChartSectionProps) => {
  const currentConfig = metricConfig[activeMetric];

  return (
    <section className="chart-section">
      <div className="chart-header">
        <h2 className="chart-title">月次実績推移グラフ</h2>
        <div className="chart-tabs" role="tablist">
          {metricTabs.map((tab) => {
            const isSelected = activeMetric === tab.id;
            const btnClass = isSelected
              ? 'chart-tab-btn chart-tab-btn-active'
              : 'chart-tab-btn';
            return (
              <button
                key={tab.id}
                type="button"
                role="tab"
                aria-selected={isSelected}
                className={btnClass}
                onClick={() => onChangeMetric?.(tab.id)}
              >
                {tab.label}
              </button>
            );
          })}
        </div>
      </div>

      <div className="chart-container">
        <ResponsiveContainer width="100%" height={360}>
          <ComposedChart
            data={data}
            margin={{ top: 20, right: 20, bottom: 20, left: 20 }}
          >
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
            <XAxis
              dataKey="month"
              tickLine={false}
              axisLine={{ stroke: '#CBD5E1' }}
              tick={{ fill: '#64748B', fontSize: 12 }}
            />
            <YAxis
              tickLine={false}
              axisLine={{ stroke: '#CBD5E1' }}
              tick={{ fill: '#64748B', fontSize: 12 }}
              tickFormatter={currentConfig.yAxisFormatter}
            />
            <Tooltip
              formatter={currentConfig.tooltipFormatter}
              contentStyle={{
                backgroundColor: '#FFFFFF',
                borderColor: '#E2E8F0',
                borderRadius: '8px',
                boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                fontSize: '13px'
              }}
            />
            <Legend verticalAlign="top" height={36} iconType="circle" />

            {activeMetric === 'sales' && (
              <>
                <Bar
                  dataKey="sales"
                  name="売上実績"
                  fill="#3B82F6"
                  radius={[4, 4, 0, 0]}
                  maxBarSize={40}
                />
                <Line
                  type="monotone"
                  dataKey="targetSales"
                  name="目標売上"
                  stroke="#F59E0B"
                  strokeWidth={2}
                  strokeDasharray="4 4"
                  dot={{ r: 4, fill: '#F59E0B' }}
                />
              </>
            )}

            {activeMetric === 'customers' && (
              <Bar
                dataKey="customers"
                name="客数"
                fill="#10B981"
                radius={[4, 4, 0, 0]}
                maxBarSize={40}
              />
            )}

            {activeMetric === 'averageSpend' && (
              <Bar
                dataKey="averageSpend"
                name="客単価"
                fill="#8B5CF6"
                radius={[4, 4, 0, 0]}
                maxBarSize={40}
              />
            )}
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
};

export default ChartSection;

import { useState, useMemo, ChangeEvent } from 'react';
import { KpiItem, KpiMetricType, YearOption, MonthlyRecord } from './types';
import { salesData2022, salesData2023, salesData2024 } from './data/mockData';
import KpiCards from './components/KpiCards';
import ChartSection from './components/ChartSection';
import './index.css';

interface TableRowData {
  month: string;
  sales: number;
  targetSales: number;
  achievementRate: number;
  achievementClass: string;
  customers: number;
  averageSpend: number;
  yoyRate: number;
  isYoyPositive: boolean;
  yoyClass: string;
}

const calculateTableRowData = (
  record: MonthlyRecord,
  prevRecord?: MonthlyRecord
): TableRowData => {
  const achievementRate =
    record.targetSales > 0 ? (record.sales / record.targetSales) * 100 : 100;
  const achievementClass = achievementRate >= 100 ? 'trend-up' : 'trend-down';

  const yoyRate =
    prevRecord && prevRecord.sales > 0
      ? ((record.sales - prevRecord.sales) / prevRecord.sales) * 100
      : 0;
  const isYoyPositive = yoyRate >= 0;
  const yoyClass = isYoyPositive ? 'trend-up' : 'trend-down';

  return {
    month: record.month,
    sales: record.sales,
    targetSales: record.targetSales,
    achievementRate,
    achievementClass,
    customers: record.customers,
    averageSpend: record.averageSpend,
    yoyRate,
    isYoyPositive,
    yoyClass
  };
};

const App = () => {
  const [selectedYear, setSelectedYear] = useState<YearOption>('2024');
  const [selectedMetric, setSelectedMetric] = useState<KpiMetricType>('sales');

  const currentYearData: MonthlyRecord[] = useMemo(() => {
    return selectedYear === '2024' ? salesData2024 : salesData2023;
  }, [selectedYear]);

  const previousYearData: MonthlyRecord[] = useMemo(() => {
    return selectedYear === '2024' ? salesData2023 : salesData2022;
  }, [selectedYear]);

  const kpis: KpiItem[] = useMemo(() => {
    const totalSales = currentYearData.reduce((acc, cur) => acc + cur.sales, 0);
    const prevTotalSales = previousYearData.reduce((acc, cur) => acc + cur.sales, 0);
    const salesDiffRate =
      prevTotalSales > 0
        ? ((totalSales - prevTotalSales) / prevTotalSales) * 100
        : 0;

    const totalCustomers = currentYearData.reduce((acc, cur) => acc + cur.customers, 0);
    const prevTotalCustomers = previousYearData.reduce((acc, cur) => acc + cur.customers, 0);
    const customersDiffRate =
      prevTotalCustomers > 0
        ? ((totalCustomers - prevTotalCustomers) / prevTotalCustomers) * 100
        : 0;

    const avgSpend = totalCustomers > 0 ? Math.round(totalSales / totalCustomers) : 0;
    const prevAvgSpend =
      prevTotalCustomers > 0 ? Math.round(prevTotalSales / prevTotalCustomers) : 0;
    const spendDiffRate =
      prevAvgSpend > 0 ? ((avgSpend - prevAvgSpend) / prevAvgSpend) * 100 : 0;

    return [
      {
        id: 'sales',
        label: '年間総売上',
        value: totalSales,
        previousValue: prevTotalSales,
        unit: ' 円',
        prefix: '¥',
        diffRate: salesDiffRate
      },
      {
        id: 'customers',
        label: '年間総客数',
        value: totalCustomers,
        previousValue: prevTotalCustomers,
        unit: ' 人',
        prefix: '',
        diffRate: customersDiffRate
      },
      {
        id: 'averageSpend',
        label: '年間平均客単価',
        value: avgSpend,
        previousValue: prevAvgSpend,
        unit: ' 円',
        prefix: '¥',
        diffRate: spendDiffRate
      }
    ];
  }, [currentYearData, previousYearData]);

  const tableRows = useMemo(() => {
    return currentYearData.map((record, index) =>
      calculateTableRowData(record, previousYearData[index])
    );
  }, [currentYearData, previousYearData]);

  const handleYearChange = (e: ChangeEvent<HTMLSelectElement>) => {
    setSelectedYear(e.target.value as YearOption);
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="header-title">売上分析ダッシュボード</h1>
          <p className="header-subtitle">
            売上・客数・平均客単価の推移と予算達成状況の可視化
          </p>
        </div>
        <div className="header-controls">
          <label htmlFor="year-select" style={{ display: 'none' }}>
            対象年度選択
          </label>
          <select
            id="year-select"
            className="year-select"
            value={selectedYear}
            onChange={handleYearChange}
          >
            <option value="2024">2024年度実績</option>
            <option value="2023">2023年度実績</option>
          </select>
        </div>
      </header>

      <main>
        <KpiCards
          kpis={kpis}
          selectedMetric={selectedMetric}
          onSelectMetric={setSelectedMetric}
        />

        <ChartSection
          data={currentYearData}
          activeMetric={selectedMetric}
          onChangeMetric={setSelectedMetric}
        />

        <section className="table-section">
          <h2 className="table-title">月別詳細実績一覧</h2>
          <div className="table-wrapper">
            <table className="data-table">
              <thead>
                <tr>
                  <th scope="col">月</th>
                  <th scope="col" className="num-cell">売上実績</th>
                  <th scope="col" className="num-cell">売上目標</th>
                  <th scope="col" className="num-cell">達成率</th>
                  <th scope="col" className="num-cell">客数</th>
                  <th scope="col" className="num-cell">平均単価</th>
                  <th scope="col" className="num-cell">前年同月比</th>
                </tr>
              </thead>
              <tbody>
                {tableRows.map((row) => (
                  <tr key={row.month}>
                    <td><strong>{row.month}</strong></td>
                    <td className="num-cell">¥{row.sales.toLocaleString()}</td>
                    <td className="num-cell">¥{row.targetSales.toLocaleString()}</td>
                    <td className={`num-cell ${row.achievementClass}`}>
                      {row.achievementRate.toFixed(1)}%
                    </td>
                    <td className="num-cell">{row.customers.toLocaleString()} 人</td>
                    <td className="num-cell">¥{row.averageSpend.toLocaleString()}</td>
                    <td className={`num-cell ${row.yoyClass}`}>
                      {row.isYoyPositive ? '+' : ''}{row.yoyRate.toFixed(1)}%
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

:root {
  --color-bg: #f8fafc;
  --color-card-bg: #ffffff;
  --color-card-border: #e2e8f0;
  --color-card-hover: #f1f5f9;
  --color-text-main: #0f172a;
  --color-text-muted: #64748b;

  --color-primary: #3b82f6;
  --color-primary-light: #eff6ff;
  --color-primary-dark: #1d4ed8;
  --color-primary-border: #93c5fd;

  --color-success: #10b981;
  --color-success-bg: #ecfdf5;
  --color-danger: #ef4444;
  --color-danger-bg: #fef2f2;

  --font-family-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family-base);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* 全体コンテナ */
.dashboard-container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

/* ヘッダー */
.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--color-card-border);
}

.header-title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-main);
}

.header-subtitle {
  font-size: 0.925rem;
  color: var(--color-text-muted);
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.year-select {
  appearance: none;
  background-color: var(--color-card-bg);
  color: var(--color-text-main);
  border: 1px solid var(--color-card-border);
  border-radius: var(--radius-md);
  padding: 9px 36px 9px 14px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  background-image: url("data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%2364748b%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%226%209%2012%2015%2018%209%22%3E%3C%2Fpolyline%3E%3C%2Fsvg%3E");
  background-repeat: no-repeat;
  background-position: right 10px center;
  box-shadow: var(--shadow-sm);
  transition: all 0.2s ease;
}

.year-select:hover {
  border-color: var(--color-primary-border);
}

.year-select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.year-select:focus-visible {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
}

/* KPIカードセクション */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
}

.kpi-card {
  background-color: var(--color-card-bg);
  border: 1px solid var(--color-card-border);
  border-radius: var(--radius-lg);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  overflow: hidden;
}

.kpi-card:hover {
  border-color: var(--color-primary-border);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.kpi-card:focus-visible {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.3);
}

.kpi-card-active {
  border-color: var(--color-primary);
  background-color: var(--color-primary-light);
  box-shadow: 0 0 0 2px var(--color-primary), var(--shadow-md);
}

.kpi-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.kpi-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.kpi-badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 9999px;
  line-height: 1.2;
}

.kpi-badge-positive {
  background-color: var(--color-success-bg);
  color: var(--color-success);
}

.kpi-badge-negative {
  background-color: var(--color-danger-bg);
  color: var(--color-danger);
}

.kpi-value-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.kpi-value {
  font-size: 2.1rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-text-main);
  line-height: 1;
}

.kpi-subtext {
  font-size: 0.825rem;
  color: var(--color-text-muted);
}

/* チャートセクション */
.chart-section {
  background-color: var(--color-card-bg);
  border: 1px solid var(--color-card-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.chart-title {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.chart-tabs {
  display: flex;
  background-color: var(--color-bg);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-card-border);
  gap: 4px;
}

.chart-tab-btn {
  background: none;
  border: none;
  padding: 6px 14px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-muted);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.chart-tab-btn:hover {
  color: var(--color-text-main);
}

.chart-tab-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-primary);
}

.chart-tab-btn-active {
  background-color: var(--color-card-bg);
  color: var(--color-primary-dark);
  box-shadow: var(--shadow-sm);
}

.chart-container {
  width: 100%;
  height: 380px;
  position: relative;
}

/* テーブルセクション */
.table-section {
  background-color: var(--color-card-bg);
  border: 1px solid var(--color-card-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.table-title {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.table-wrapper {
  overflow: hidden;
  overflow-x: auto;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-card-border);
}

.table-wrapper:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-primary);
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.925rem;
}

.data-table th {
  background-color: var(--color-bg);
  color: var(--color-text-muted);
  font-weight: 600;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-card-border);
  white-space: nowrap;
}

.data-table td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--color-card-border);
  color: var(--color-text-main);
  white-space: nowrap;
}

.data-table tbody tr:last-child td {
  border-bottom: none;
}

.data-table tbody tr:hover {
  background-color: var(--color-card-hover);
}

.num-cell {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
}

.trend-up {
  color: var(--color-success);
  font-weight: 600;
}

.trend-down {
  color: var(--color-danger);
  font-weight: 600;
}

/* レスポンシブ調整 */
@media (max-width: 768px) {
  .dashboard-container {
    padding: 16px 12px 32px;
    gap: 20px;
  }

  .dashboard-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .header-controls {
    width: 100%;
  }

  .year-select {
    width: 100%;
  }

  .chart-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .chart-tabs {
    width: 100%;
    justify-content: space-between;
  }

  .chart-tab-btn {
    flex: 1;
    text-align: center;
    padding: 8px 4px;
    font-size: 0.8rem;
  }

  .chart-container {
    height: 300px;
  }

  .kpi-value {
    font-size: 1.8rem;
  }
}
